python3 -c "
import json
with open('/app/benchmark/source_data.json') as f:
    data = json.load(f)
nodes = {n['id']: n for n in data['architecture']['nodes']}
edges = data['architecture']['edges']
conn = {}
for e in edges:
    s, t = e['source'], e['target']
    if nodes[s]['type'] in ('observability','service_mesh_control') or nodes[t]['type'] in ('observability','service_mesh_control'):
        continue
    conn[s] = conn.get(s, 0) + 1
    conn[t] = conn.get(t, 0) + 1
for k, v in sorted(conn.items(), key=lambda x: -x[1]):
    print(f'{k:30s} tier={nodes[k][\"tier\"]:10s} type={nodes[k][\"type\"]:20s} conn={v}')
"

